nt-family:'DM Mono';font-size:8px;letter-spacing:.15em;color:#a6bac8}.speed-ring{position:absolute;inset:0;border:1px solid #ffffff24;border-radius:50%;clip-path:polygon(0 0,100% 0,100% 70%,50% 100%,0 70%)}.speed-ring i{position:absolute;top:2px;left:14px;width:5px;height:5px;border-radius:50%;background:var(--blue);box-shadow:0 0 8px var(--blue)}.controls-hint{position:absolute;z-index:2;bottom:47px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:5px;color:#94a8b8;font-family:'DM Mono';font-size:8px;letter-spacing:.09em;white-space:nowrap}.controls-hint kbd{width:18px;height:18px;display:grid;place-items:center;border:1px solid #ffffff38;background:#0a1927b8;border-radius:3px;color:#e0eaf0;font:10px 'DM Mono';box-shadow:0 2px 0 #ffffff17}.controls-hint kbd.wide{width:42px;font-size:8px;margin-left:6px}.controls-hint span{margin:0 5px 0 2px}.pause-button{position:absolute;right:4.3%;top:94px;z-index:3;width:30px;height:30px;border:1px solid #ffffff26;background:#0a1927aa;color:#cfdae1;cursor:pointer;border-radius:3px}.pause-button:hover{border-color:var(--blue);color:var(--blue)}.pause-button span{font-size:13px}.screen-overlay{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:flex-start;padding:8% 0 0 11%;background:linear-gradient(90deg,rgba(4,11,19,.82),rgba(4,11,19,.46) 43%,rgba(4,11,19,.05) 80%);backdrop-filter:blur(1px)}.screen-overlay.hidden{display:none}.menu-card{width:min(405px,45vw);padding:30px 0}.eyebrow{display:flex;align-items:center;gap:9px;font-family:'DM Mono';font-size:9px;letter-spacing:.18em;color:#b7c8d4}.eyebrow span{width:5px;height:5px;background:var(--blue);box-shadow:0 0 9px var(--blue)}.menu-card h1,.menu-card h2{margin:23px 0 15px;font-family:'Barlow Condensed';font-weight:900;font-size:clamp(68px,8.5vw,110px);line-height:.78;letter-spacing:-.025em;color:#f5f8fa}.menu-card h1 em,.menu-card h2 em{font-style:normal;color:var(--blue)}.menu-card p{font-size:13px;line-height:1.75;color